<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { LanguageSwitcherContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: LanguageSwitcherContract  = $props();
const open=control(()=>p.open,untrack(()=>p.defaultOpen),false,open=>p.onOpenChange?.({open}));const uid=$props.id();let root:HTMLElement;onMount(()=>{const outside=(e:PointerEvent)=>{if(!root.contains(e.target as Node))open.request(false);};document.addEventListener('pointerdown',outside);return()=>document.removeEventListener('pointerdown',outside);});let trigger=$state<HTMLButtonElement>();function key(e:KeyboardEvent){if(!ignoredKey(e)&&e.key==='Escape'&&open.value){e.preventDefault();open.request(false);void tick().then(()=>{if(!open.value)trigger?.focus();});}}
</script>
<nav bind:this={root} {...owned('language-switcher','root')} aria-label="언어 선택" onkeydown={key}>{#if p.options.length>2}<button bind:this={trigger} type="button" {...owned('language-switcher','trigger')} aria-expanded={open.value} aria-controls={uid} onclick={()=>open.request(!open.value)}>언어: <span {...owned('language-switcher','current')}>{p.options.find(x=>x.locale===p.currentLocale)?.nativeLabel}</span></button>{/if}<ul id={uid} hidden={p.options.length>2&&!open.value} {...owned('language-switcher','list')}>{#each p.options as option(option.locale)}<li><a {...owned('language-switcher','option',p.currentLocale===option.locale&&'current')} lang={option.locale} hreflang={option.locale} href={option.href} aria-describedby={`${uid}-${option.locale}-description`} aria-current={p.currentLocale===option.locale?'true':undefined} target={option.separateService?'_blank':undefined} rel={option.separateService?'noopener noreferrer':undefined} onclick={()=>{if(option.locale!==p.currentLocale)p.onLocaleRequest?.({locale:option.locale,href:option.href});}}>{option.nativeLabel}</a>{' '}<span id={`${uid}-${option.locale}-description`} lang="ko">({option.translatedLabel}){option.separateService?' (새 창)':''}</span></li>{/each}</ul></nav>
